              '好感度': { val: _.get(data, '禁忌之地.好感度', 0), min: -100, max: 500, stages: { "-100": "憎惡之淵", "0": "冷漠之牆", "100": "尋常親情", "200": "深厚母愛", "300": "至愛至寶", "400": "靈魂羈絆" } },
              '墮落值': { val: _.get(data, '禁忌之地.墮落值', 0), min: -100, max: 500, stages: { "-100": "聖域堅壁", "0": "母性邊界", "100": "曖昧萌芽", "200": "禁忌漣漪", "300": "欲望溫床", "400": "沉淪愛戀", "500": "永恆誓約" } },
              '情慾值': { val: _.get(data, '禁忌之地.情慾值', 0), min: -100, max: 500, stages: { "-100": "心如止水", "0": "微風拂面", "100": "春水初生", "200": "暗流湧動", "300": "情潮難禁", "400": "烈火燎原" } },
              '心情值': { val: _.get(data, '禁忌之地.心情值', 0), min: -100, max: 500, stages: { "-100": "悲傷之雨", "0": "烏雲密佈", "100": "風平浪靜", "200": "晴空萬里", "300": "暖陽和煦", "400": "幸福滿溢" } }
          };

          Object.keys(stagesConfig).forEach(key => {
              const config = stagesConfig[key];
              const totalRange = config.max - config.min;
              const currentValue = config.val - config.min;
              const percentage = (currentValue / totalRange) * 100;
              let currentStage = '';
              const sortedKeys = Object.keys(config.stages).map(Number).sort((a, b) => a - b);
              for (let i = sortedKeys.length - 1; i >= 0; i--) {
                  if (config.val >= sortedKeys[i]) {
                      currentStage = config.stages[sortedKeys[i]];
                      break;
                  }
              }
              const id_key = key === '好感度' ? 'koukando' : (key === '墮落值' ? 'daraku' : (key === '情慾值' ? 'jouyoku' : 'kibun'));
              $(`#var-${id_key}-stage`).text(currentStage);
              $(`#var-${id_key}-bar`).css('width', percentage + '%');
          });

          /* Risk Tab */
          $('#risk-location').text(_.get(data, '風險.位置', '--'));
          $('#risk-next-action').text(_.get(data, '風險.下一步行動', '--'));
          const keikaiValue = _.get(data, '風險.警戒值', 0);
          const keikaiStages = { "0": "安然無憂", "100": "偶有閑言", "200": "疑心暗種", "300": "暗中觀察", "400": "風暴前夕", "500": "定罪之時" };
          let keikaiStageText = '';
          const sortedKeikaiKeys = Object.keys(keikaiStages).map(Number).sort((a, b) => a - b);
          for (let i = sortedKeikaiKeys.length - 1; i >= 0; i--) {
              if (keikaiValue >= sortedKeikaiKeys[i]) {
                  keikaiStageText = keikaiStages[sortedKeikaiKeys[i]];
                  break;
              }
          }
          const keikaiPercentage = (keikaiValue / 600) * 100;
          $('#risk-keikai-stage').text(keikaiStageText);
          $('#risk-keikai-bar').css('width', keikaiPercentage + '%');
          $('#risk-perspective').text(_.get(data, '風險.眼中的兩人', '--'));
      }

      $(() => errorCatched(init)());
    </script>
</head>
